CREATE TABLE "training_plans" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user_id" BIGINT NOT NULL,
    "dog_id" BIGINT NOT NULL,
    "status" VARCHAR(20) NOT NULL,
    "mode" VARCHAR(20) NOT NULL,
    "generator" VARCHAR(20) NOT NULL,
    "title" VARCHAR(20) NOT NULL,
    "goal" VARCHAR(60) NOT NULL,
    "reason" VARCHAR(150) NOT NULL,
    "adjusted_reason" VARCHAR(30),
    "duration_weeks" INT NOT NULL,
    "daily_minutes" INT NOT NULL,
    "days_per_week" INT NOT NULL,
    "started_on" DATE NOT NULL,
    "target_end_on" DATE NOT NULL,
    "completed_at" TIMESTAMP,
    "outcome" VARCHAR(20),
    "interview_json" TEXT NOT NULL,
    "created_at" TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP NOT NULL
);

-- 사용자당 진행 중인 플랜은 하나만 허용한다
CREATE UNIQUE INDEX "uk_training_plans_user_id_active" ON "training_plans" ("user_id") WHERE "status" = 'ACTIVE';
CREATE INDEX "idx_training_plans_user_id_status" ON "training_plans" ("user_id", "status");

CREATE TABLE "training_plan_weeks" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "plan_id" BIGINT NOT NULL REFERENCES "training_plans" ("id"),
    "week_no" INT NOT NULL,
    "theme" VARCHAR(20) NOT NULL,
    "milestone" VARCHAR(40) NOT NULL,
    "created_at" TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP NOT NULL,
    CONSTRAINT "uk_training_plan_weeks_plan_id_week_no" UNIQUE ("plan_id", "week_no")
);

-- 커리큘럼은 마스터 데이터라 외래 키를 두지 않는다
CREATE TABLE "training_plan_items" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "plan_id" BIGINT NOT NULL REFERENCES "training_plans" ("id"),
    "week_no" INT NOT NULL,
    "curriculum_id" BIGINT NOT NULL,
    "sort_order" INT NOT NULL,
    "created_at" TIMESTAMP NOT NULL,
    "updated_at" TIMESTAMP NOT NULL,
    CONSTRAINT "uk_training_plan_items_plan_id_curriculum_id" UNIQUE ("plan_id", "curriculum_id")
);
